body:
Hi,
We have a need for custom serialization in asp.net core and have implemented a TextOutputFormatter that serialize specific entity to Json format. In that context have a custom TextOutputFormatter that serialize the content to Json.

Sample implementation is as follows:

```
    public class CustomerItemResponseFormatter : TextOutputFormatter
    {
        private const string ContentType = "application/json;odata.streaming=true";

        public CustomerItemResponseFormatter() : base()
        {
            SupportedMediaTypes.Add(MediaTypeHeaderValue.Parse(ContentType));
            SupportedEncodings.Add(Encoding.UTF8);
        }

        public override bool CanWriteResult(OutputFormatterCanWriteContext context)
        {
            return context.Object is CustomerItemResponse;
        }
        public override async Task WriteResponseBodyAsync(OutputFormatterWriteContext context, Encoding selectedEncoding)
        {
            CustomerItemResponse itemResponse = context.Object as CustomerItemResponse;
            if (itemResponse != null)
            {
                var response = context.HttpContext.Response;
                response.ContentType = ContentType;

                var pipeWriter = context.HttpContext.Response.BodyWriter;
                await WriteCustomerJsonData(pipeWriter, itemResponse);
            }
        }
     }
     
     public async Task WriteCustomerJsonData(PipeWriter pipeWriter,  CustomerItemResponse response)
     {
           PipeReader pipeReader = response.GetCustomerPicture();
           await pipeWriter.WriteAsync(response.Name);
           await pipeWriter.WriteAsync(response.Address);
           while (true)
           {
                 ReadResult result = pipeReader.ReadAsync();
                 ReadOnlySequence<byte> resultByte = result.Buffer
                 pipeWrite.WriteAsync(resultByte);
           }
     }
      
```

While testing in a single box setup (client and service are running in same box), the latency for reading 1MB data is approx 330 ms vs when I do not pipeWriter.WriteAsync then the latency comes down to 70 ms.

I understand that writing to the wire is taking time. But why does 75% of the time goes in this in a single box setup.
Is the data getting buffered or are we approaching the custom serialization in incorrect manner ?

Any guidance suggestions on how to implement this kind of custom serialization with low latency. 

Thank you
